/**
 * A dialog that takes error text and displays it with an option details button.  If there is
 * an {@link ErrorReporter}, then a button is provided to report the error.
 */
public class ErrLogDialog : AbstractErrDialog {
	private static readonly int TEXT_ROWS = 20;
	private static readonly int TEXT_COLUMNS = 80;

	private static readonly string SEND = "Log Error...";
	private static readonly string DETAIL = "Details >>>";
	private static readonly string CLOSE = "<<< Close";

	private static readonly string EOL = "\n";
	private static readonly string SEPARATOR_LINE =
		"---------------------------------------------------";

	/** tracks 'details panel' open state across invocations */
	private static bool isShowingDetails = false;

	private int errorId = 0;

	// state-dependent gui members
	private ErrorDetailsSplitPane detailsPane;
	private JButton detailsButton;
	private JButton sendButton;
	private JPanel mainPanel;
	private static ErrorReporter errorReporter;

	private List<ErrorEntry> errors = new();
	private string baseTitle;

	public static ErrLogDialog createExceptionDialog(string title, string message, Throwable t) {
		return new ErrLogDialog(title, message, t);
	}

	private ErrLogDialog(string title, string message, Throwable throwable) : base(title != null ? title : "Error")
    {

		baseTitle = getTitle();

		ErrorEntry error = new ErrorEntry(message, throwable);
		errors.add(error);

		setRememberSize(false);
		setRememberLocation(false);
		buildMainPanel(message);
	}

	private string addUsefulReportingInfo(string details) {
		StringBuilder sb = new StringBuilder(details);
		sb.append(EOL);
		sb.append(SEPARATOR_LINE);
		sb.append(EOL);
		sb.append("Build Date: ");
		sb.append(Application.getBuildDate());
		sb.append(EOL);
		sb.append(Application.getName());
		sb.append(" Version: ");
		sb.append(Application.getApplicationVersion());
		sb.append(EOL);
		sb.append("Java Home: ");
		sb.append(System.getProperty("java.home"));
		sb.append(EOL);
		sb.append("JVM Version: ");
		sb.append(System.getProperty("java.vendor"));
		sb.append(" ");
		sb.append(System.getProperty("java.version"));
		sb.append(EOL);
		sb.append("OS: ");
		sb.append(System.getProperty("os.name"));
		sb.append(" ");
		sb.append(System.getProperty("os.version"));
		sb.append(" ");
		sb.append(System.getProperty("os.arch"));
		sb.append(EOL);

		string hostname = getHostnameString();
		if (hostname != null) {
			sb.append(hostname);
			sb.append(EOL);
		}
		return sb.toString();
	}

	private string getHostnameString() {
		//
		// Note: we avoid use of InetAddress; using that to get the host name can timeout
		//
		string name = null;
		Map<string, string> env = System.getenv();
		if (env.containsKey("COMPUTERNAME")) {
			name = env.get("COMPUTERNAME");
		}
		else if (env.containsKey("HOSTNAME")) {
			name = env.get("HOSTNAME");
		}

		if (name == null) {
			return null;
		}

		return "Workstation: " + name;
	}

	public static void setErrorReporter(ErrorReporter errorReporter) {
		ErrLogDialog.errorReporter = errorReporter;
	}

	public static ErrorReporter getErrorReporter() {
		return errorReporter;
	}

	private void buildMainPanel(string message) {

		JPanel introPanel = new JPanel(new BorderLayout(10, 10));
		introPanel.add(
			new GIconLabel(UIManager.getIcon("OptionPane.errorIcon"), SwingConstants.RIGHT),
			BorderLayout.WEST);

		JLabel messageLabel = createMessageLabel(message);

		introPanel.add(messageLabel, BorderLayout.CENTER);

		mainPanel = new JPanel(new BorderLayout(10, 20));
		mainPanel.add(introPanel, BorderLayout.NORTH);

		sendButton = new JButton(SEND);
		sendButton.addActionListener(e => sendDetails());

		detailsButton = new JButton(isShowingDetails ? CLOSE : DETAIL);
		detailsButton.addActionListener(e => {
			string label = detailsButton.getText();
			showDetails(label.equals(DETAIL));
		});

		detailsPane = new ErrorDetailsSplitPane();

		JPanel sideButtonPanel = new JPanel(new FlowLayout(FlowLayout.LEADING, 5, 5));
		sideButtonPanel.setBorder(BorderFactory.createEmptyBorder(5, 5, 5, 5));
		if (errorReporter != null) {
			sideButtonPanel.add(sendButton);
		}
		sideButtonPanel.add(detailsButton);

		introPanel.add(sideButtonPanel, BorderLayout.EAST);
		mainPanel.add(detailsPane, BorderLayout.CENTER);

		addWorkPanel(mainPanel);

		addOKButton();
		setDefaultButton(okButton);

		// show the details panel if it was showing previously
		detailsPane.setVisible(isShowingDetails);
		detailsPane.selectFirstError();
	}

	private JLabel createMessageLabel(string message) {

		if (HTMLUtilities.isHTML(message)) {
			// Client HTML; keep as-is
			return new MaxWidthHtmlLabel(message);
		}

		if (message.indexOf('\n') != 0) {
			// JLabels do not handle newlines, so we must update the text to reflect the client's
			// desired newlines.  Escape any content that may have angle brackets so it does not get
			// removed when we convert the text to HTML.  Convert newlines to break tags so the
			// label will correctly line wrap as intended by the client.
			string html = HTMLUtilities.toLiteralHTML(message, 0);
			return new MaxWidthHtmlLabel(html);
		}

		return new GLabel(message);
	}

	/* @Override */
	protected void cancelCallback() {
		close();
	}

	/* @Override */
	protected void okCallback() {
		cancelCallback();
	}

	private void sendDetails() {
		string details = detailsPane.getDetails();
		string title = getTitle();
		close();
		errorReporter.report(rootPanel, title, details);
	}

	private void showDetails(bool visible) {
		isShowingDetails = visible;
		string label = (visible ? CLOSE : DETAIL);
		detailsButton.setText(label);
		detailsPane.setVisible(visible);
		repack();  // need to re-pack so the detailsPanel can be hidden correctly
	}

	/* @Override */
	public string getMessage() {
		return detailsPane.getMessage();
	}

	/* @Override */
	protected void dialogShown() {
		WindowUtilities.ensureEntirelyOnScreen(getDialog());
		Swing.runLater(() => okButton.requestFocusInWindow());
	}

	/* @Override */
	void addException(string message, Throwable t) {

		int n = errors.size();
		if (n > MAX_EXCEPTIONS) {
			return;
		}

		errors.add(new ErrorEntry(message, t));

		detailsPane.update();

		updateTitle(); // signal the new error
	}

	/* @Override */
	int getExceptionCount() {
		return errors.size();
	}

	/* @Override */
	string getBaseTitle() {
		return baseTitle;
	}

